-- Second Spanish article translations batch (deepening phase). Same 3
-- additional articles as the German batch 2: Things to do in Maldives,
-- Most Famous Places In The World, and the Maldives Honeymoon guide.
-- entity_id resolved via scalar subquery on the canonical English slug
-- (see the entity_id fix commit for why this matters).
insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ((select id from nodes where node_type = 'article' and slug = 'things-to-do-in-maldives'), 'article', 'es', 'cosas-que-hacer-en-maldivas', 'Cosas que hacer en Maldivas', 'Las 12 mejores actividades para hacer en Maldivas durante sus vacaciones. La mayoría de estas actividades están disponibles en todos los resorts.', null, '<h3>Buceo con tubo (snorkel)</h3><p>Maldivas ofrece algunas de las experiencias de snorkel más espectaculares del mundo. Esto se debe a la abundancia de arrecifes de coral en la región, así como a la extrema claridad de sus aguas. De hecho, existen cerca de 70 especies distintas de arrecifes de coral y más de 700 especies de vida marina. Esto significa que, al hacer snorkel aquí, sin duda verá una asombrosa variedad de flora y fauna. Algunas de las especies que probablemente verá incluyen tiburones de arrecife, varios tipos de tortugas, rayas, peces napoleón y morenas. Ya sea que sea experto en vida marina o no, podrá apreciar la colorida variedad de criaturas que logrará observar. El snorkel es una actividad muy recomendada en Maldivas.</p><figure><img src="legacy/images/articles/snorkeling.webp" alt="maldives" loading="lazy" /></figure><h3>Buceo</h3><p>Maldivas se ha convertido en uno de los mejores destinos de buceo del mundo gracias a sus playas de arena blanca, arrecifes de coral, aguas cálidas y transparentes, numerosos puntos de buceo y una rica vida marina.</p><p>La mayoría de los resorts de Maldivas cuentan con instalaciones de buceo, y existen varios operadores de cruceros liveaboard que ofrecen vacaciones de buceo que llevan a los huéspedes a muchos puntos de inmersión por todo el archipiélago. Muchos buceadores desean sumergirse en Maldivas por la presencia de tiburones ballena, mantarrayas, rayas águila, tiburones de arrecife, tiburones martillo y morenas, además de muchas especies más pequeñas de peces y corales. El buceo es una de las mejores actividades que se pueden hacer en Maldivas.</p><figure><img src="legacy/images/articles/maldives-diving.webp" alt="maldives" loading="lazy" /></figure><h3>Pesca</h3><p>Reconocida como uno de los mejores destinos del mundo para la pesca de altura, Maldivas alberga una abundancia de peces pelágicos como el atún, el dorado, la peto, el barracuda y el pez espada. Maldivas cuenta con estrictas regulaciones de pesca que se hacen cumplir ampliamente para mantener las poblaciones de peces que sostienen el sustento de la población local.</p><figure><img src="legacy/images/articles/fishing.webp" alt="maldives" loading="lazy" /></figure><h3>Playas</h3><p>Las playas de Maldivas son famosas por su blancura y sus aguas cristalinas. En algunas zonas de Maldivas, las playas pueden brillar durante la noche, fenómeno causado por el plancton marino. La playa de <a href="/maldives/islands/fuvahmulah/">Fuvahmulah</a> es famosa por sus piedras brillantes.</p><figure><img src="legacy/images/articles/maldives-sand-bank.webp" alt="maldives" loading="lazy" /></figure><h3>Yoga</h3><p>El yoga es un conjunto de prácticas físicas, mentales y espirituales que se originaron en la antigua India. El yoga es una de las seis escuelas ortodoxas de las tradiciones filosóficas hindúes. Los resorts de Maldivas ofrecen una amplia variedad de sesiones de yoga; el mejor momento para practicarlo es durante el amanecer y el atardecer.</p><h3>Spa</h3><p>Casi todos los resorts de Maldivas ofrecen muchos tipos de masajes corporales. También hay disponibles numerosas marcas de spa internacionalmente reconocidas.</p><h3>Cenas bajo el agua</h3><p>Maldivas cuenta con el primer restaurante submarino del mundo. En total hay 6 restaurantes submarinos disponibles en distintas zonas. Construidos a varios metros bajo el nivel del mar, estos restaurantes ofrecen vistas impresionantes de la vida marina a través de techos de cristal, redefiniendo por completo la experiencia de cenar bajo el agua en Maldivas.</p><h3>Recorrido por las islas</h3><p>Recorrer varias islas es la mejor manera de descubrir la cultura y la historia local de Maldivas. Hay 200 islas locales en todo el archipiélago, y casi todos los resorts y hoteles ofrecen excursiones para que los turistas visiten estas islas locales.</p><p>La ciudad de Malé es la capital de Maldivas y un gran lugar con numerosos sitios importantes e interesantes. Si se alojan en un resort, la mejor manera de visitar la capital es el día de su partida: llegue antes al aeropuerto internacional de Malé y tome el trayecto de 10 minutos desde el aeropuerto. Esta es una de las mejores actividades si tiene tiempo de espera en el aeropuerto de Malé.</p><figure><img src="legacy/images/articles/day-tours-to-villages.webp" alt="maldives" loading="lazy" /></figure><h3>Submarino para observar ballenas</h3><p>El submarino para observar ballenas es la mejor opción para quienes no saben nadar o bucear. La vida marina de Maldivas es el tesoro más rico del país. Si por alguna razón no puede bucear o sumergirse bajo el agua, no se preocupe: Maldivas ofrece excursiones en submarino para observar ballenas.</p><h3>Surf</h3><p>El surf en Maldivas está condicionado por los monzones del noreste y del suroeste. Durante el monzón del noreste (de marzo a abril), las condiciones son óptimas en los atolones del sur. De mayo a octubre, durante el monzón del suroeste, la mejor zona de surf se encuentra en los atolones del norte o del centro.</p><h3>Compras en Maldivas</h3><p>Las compras de recuerdos son muy populares entre los visitantes en Maldivas. Las tiendas de recuerdos ofrecen artículos hechos localmente, corales, conchas y muchos objetos artesanales. La ciudad de Malé es el lugar más destacado para comprar recuerdos; también están disponibles las compras en línea y la entrega a domicilio.</p><figure><img src="legacy/images/articles/maldives-shopping.webp" alt="maldives" loading="lazy" /></figure><h3>Excursiones y deportes acuáticos</h3><p>Existen muchos otros tipos de excursiones y deportes acuáticos que se ofrecen en Maldivas. A continuación, algunas de las excursiones más comunes.</p><p>Observación de mantarrayas Observación de ballenas Observación de delfines Alimentación de tiburones Alimentación de rayas Crucero al atardecer Crucero al amanecer Excursión al ecuador</p><p>Moto de agua Paseo en banana boat Kayak Windsurf Parasailing Esquí acuático Paseo en catamarán</p><figure><img src="legacy/images/articles/dolphin-cruise.webp" alt="maldives" loading="lazy" /></figure>', 'Cosas que hacer en Maldivas | Guía de Viaje a Maldivas | MTG', 'Las 12 mejores actividades para hacer en Maldivas durante sus vacaciones. La mayoría de estas actividades están disponibles en todos los resorts.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'most-famous-places-in-the-world'), 'article', 'es', 'los-lugares-mas-famosos-del-mundo', 'Los lugares más famosos del mundo', 'Lista de los lugares y destinos más famosos del mundo con datos interesantes para turistas.', null, '<p>Autor: Shayad Saeed</p><p>Fecha: 02/02/2021</p><p>Existen cientos de lugares famosos en el mundo, y de entre ellos destacaré los 10 más conocidos según mis investigaciones. Los monumentos nos dan un sentido de lugar. Estos sitios históricos y maravillas naturales nos conectan con un lugar y nos invitan a visitarlo. La Torre Eiffel se encuentra en París, y la Estatua de la Libertad se encuentra en la ciudad de Nueva York. Estas 10 atracciones, todas significativas para sus respectivas ubicaciones e historias, deberían estar en su lista de viajes pendientes.</p><figure><img src="legacy/images/articles/ar/famous-places-in-the-world.webp" alt="famous places in the world" loading="lazy" /></figure><h4>Burj Khalifa, Dubái</h4><p>En Dubái, Emiratos Árabes Unidos, el Burj Khalifa es un rascacielos. Es la estructura y edificio más alto del mundo desde 2009, con una altura total de 829,8 m (poco más de media milla), superando al anterior récord, el Taipei 101. Los siguientes registros están asociados con el Burj Khalifa:</p><p>Estos registros lo convierten en uno de los mejores lugares del mundo.</p><figure><img src="legacy/images/articles/ar/famous-places-on-the-world.webp" alt="famous places on the world" loading="lazy" /></figure><h4>La Torre Eiffel, Francia</h4><p>La Torre Eiffel, también conocida como La Tour Eiffel en francés, fue la pieza central de la Exposición de París de 1889. Se construyó para celebrar el centenario de la Revolución Francesa y para mostrar al resto del mundo la pujanza industrial de Francia. Más tarde se convirtió en el símbolo de la ciudad por las siguientes razones:</p><figure><img src="legacy/images/articles/ar/most-famous-places-in-the-world.webp" alt="most famous places in the world" loading="lazy" /></figure><h4>La Ópera de Sídney</h4><p>La Ópera de Sídney es un centro de artes escénicas con varios recintos en Sídney, Nueva Gales del Sur, Australia, situado en el puerto de Sídney. Es una de las estructuras más conocidas y distintivas del siglo XX.</p><figure><img src="legacy/images/articles/ar/famous-destinations-in-the-world.webp" alt="famous destinations in the world" loading="lazy" /></figure><h4>Estatua de la Libertad: Nueva York</h4><p>La Estatua de la Libertad es uno de los monumentos más conocidos de los Estados Unidos, situada en el puerto de Nueva York. El monumento fue construido en 1886 por el pueblo francés para simbolizar la amistad entre ambos países, y fue declarado Monumento Nacional en 1924. Se puede acceder a la estatua en ferry desde Battery Park, en el Bajo Manhattan, que se detiene tanto en la isla Ellis como en la isla Liberty.</p><figure><img src="legacy/images/articles/ar/best-places-in-the-world.webp" alt="best places in the world" loading="lazy" /></figure><h4>La Gran Pirámide de Guiza: El Cairo, Egipto</h4><p>La Gran Pirámide de Guiza y las pirámides que la rodean datan de hace más de 4.000 años. Se encuentran a las afueras de El Cairo, junto al río Nilo. Construidas alrededor del año 2500 a. C. por el rey Keops, estas ruinas antiguas son también una de las Siete Maravillas del Mundo Antiguo, y la única que aún sigue en pie.</p><figure><img src="legacy/images/articles/ar/famous-destinations.webp" alt="famous destinations" loading="lazy" /></figure><h4>Marina Bay Sands, Singapur</h4><p>El Marina Bay Sands es un hotel y centro comercial en el distrito Downtown Core de Singapur. Al abrir sus puertas en 2010, se anunció como la propiedad de casino independiente más cara del mundo, con un costo de 8.000 millones de dólares singapurenses (6.880 millones de dólares estadounidenses), incluido el terreno.</p><figure><img src="legacy/images/articles/ar/famous-places.webp" alt="famous places" loading="lazy" /></figure><h4>Taj Mahal: Agra, India</h4><p>El Taj Mahal fue construido para la esposa del emperador Shah Jahan. La UNESCO ha designado este edificio, terminado en 1648, como el mejor ejemplo de arquitectura indo-islámica. El Taj Mahal se encuentra en la ciudad de Agra y se puede llegar desde la capital, Nueva Delhi, con un vuelo de una hora o un viaje en tren de tres horas. Debido a las grandes multitudes en esta atracción, es mejor visitarlo durante la semana. El amanecer proyecta un resplandor encantador sobre la estructura de mármol blanco.</p><figure><img src="legacy/images/articles/ar/famous-places-to-visit-in-the-world.webp" alt="famous places to visit in the world" loading="lazy" /></figure><h4>Islas Maldivas</h4><p>Las Maldivas son una cadena de 1.200 islas situadas en el océano Índico. Las Maldivas son conocidas por su singularidad y belleza natural. Por su posición geográfica, lo mejor es visitarlas entre octubre y mayo. Por las siguientes razones, se consideran uno de los mejores lugares para visitar:</p><figure><img src="legacy/images/articles/ar/best-places-to-tavel-in-the-world.webp" alt="best places to tavel in the world" loading="lazy" /></figure><h4>Isla de Bora Bora</h4><p>Bora Bora es una pequeña isla frente a la costa de la Polinesia (de solo unos 10 km de largo y poco más de 3 km de ancho). En su centro se encuentra un volcán inactivo que se abre hacia una exuberante selva antes de desembocar en una laguna de color turquesa. Estos detalles la convierten en uno de los mejores destinos de viaje:</p><figure><img src="legacy/images/articles/ar/famous-places-to-travel-in-the-world.webp" alt="famous places to-travel in the world" loading="lazy" /></figure><h4>Isla Sur, Nueva Zelanda</h4><p>La Isla Sur de Nueva Zelanda rebosa de paisajes majestuosos en cada rincón, y es una Zona del Patrimonio Mundial de la UNESCO. Los siguientes datos la convierten en uno de los lugares más famosos para viajar.</p>', 'Los lugares más famosos del mundo | Guía de Viaje a Maldivas | MTG', 'Lista de los lugares y destinos más famosos del mundo con datos interesantes para turistas.', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-honeymoon-ultimate-romantic-getaway-guide'), 'article', 'es', 'luna-de-miel-en-maldivas-guia-romantica-definitiva', 'Luna de miel en Maldivas: La guía definitiva para una escapada romántica', 'Guía completa de luna de miel en Maldivas: descubra los mejores resorts románticos, bungalows sobre el agua, paquetes y experiencias únicas para su escapada en pareja perfecta en el paraíso.', null, '<figure><img src="legacy/images/maldives-honeymoons.webp" alt="Romantic Maldives honeymoon couple on beach" loading="lazy" /></figure><p>Maldivas se consolida como el paraíso indiscutible para las lunas de miel, ofreciendo a los recién casados una exquisita combinación de belleza natural, privacidad y romance. Este archipiélago de 1.192 islas de coral repartidas por el océano Índico ha perfeccionado el arte de las vacaciones en pareja, con resorts diseñados específicamente para crear experiencias románticas inolvidables.</p><p>Lo que distingue a Maldivas de otros destinos tropicales es su geografía única: cada resort suele ocupar su propia isla privada, lo que garantiza un aislamiento total. Los icónicos bungalows sobre el agua, que Maldivas fue pionera en introducir, permiten a las parejas despertar con el suave sonido de las olas bajo su villa y sumergirse directamente en lagunas de aguas cristalinas.</p><p>Más allá de la belleza física, los resorts maldivos se especializan en crear experiencias románticas personalizadas. Desde picnics privados en bancos de arena hasta comedores submarinos rodeados de vida marina, las oportunidades para crear momentos especiales son infinitas. La cultura musulmana del país implica que las muestras públicas de afecto se reservan para las islas resort, creando una atmósfera discreta e íntima, perfecta para las lunas de miel.</p><h2>Por qué Maldivas es el destino definitivo para la luna de miel</h2><figure><img src="legacy/images/activities/virgin-islands-excursion.webp" alt="Private island in Maldives" loading="lazy" /></figure><p>Varios factores clave convierten a Maldivas en el principal destino de luna de miel del mundo:</p><h4>1. Privacidad incomparable</h4><p>A diferencia de los destinos de playa abarrotados, los resorts maldivos ofrecen un verdadero aislamiento. La mayoría ocupan islas privadas con solo entre 50 y 150 villas, lo que significa que a menudo tendrá tramos enteros de playa para usted solo. Las islas resort están cuidadosamente diseñadas para maximizar la privacidad, con barreras de vegetación entre los alojamientos.</p><h4>2. La experiencia del bungalow sobre el agua</h4><p>Maldivas inventó el concepto de la villa de lujo sobre el agua. Las versiones modernas incluyen paneles de suelo de cristal, piscinas infinitas privadas y acceso directo a la laguna. Lea nuestra guía completa sobre los bungalows sobre el agua de Maldivas para elegir el perfecto.</p><h4>3. Romance todo incluido</h4><p>Los resorts se especializan en experiencias románticas sin complicaciones. Los mayordomos pueden organizar todo, desde propuestas de matrimonio sorpresa hasta celebraciones de aniversario. La mayoría ofrece paquetes especiales de luna de miel con detalles románticos incluidos.</p><h4>4. Clima cálido todo el año</h4><p>Con temperaturas promedio de 28 a 30 °C y temperaturas del agua de alrededor de 27 °C durante todo el año, Maldivas siempre está lista para una luna de miel. Aunque existe una temporada de lluvias, los chubascos suelen ser breves.</p><h4>5. Vida marina incomparable</h4><p>Los atolones de coral de Maldivas crean condiciones perfectas para una diversa vida marina. Muchos resorts tienen excelentes arrecifes propios donde se puede hacer snorkel con tortugas, rayas y peces tropicales directamente desde su villa.</p><h2>Los 5 mejores resorts de Maldivas para lunas de miel</h2><figure><img src="legacy/resorts/four-seasons-huraa/images/four-seasons-maldives-at-kuda-huraa-sunset-water-bangalow1.webp" alt="Four Seasons Kuda Huraa overwater bungalow" loading="lazy" /></figure><h3>1. Four Seasons Resort Maldives at Kuda Huraa</h3><p>Esta legendaria propiedad marca el estándar para las lunas de miel en Maldivas, ofreciendo:</p><ul><li>Bungalows sobre el agua recién renovados con servicio de mayordomo 24/7</li><li>Piscinas infinitas privadas en las villas premium</li><li>Spa de fama mundial con salas de tratamiento sobre el agua</li><li>Siete restaurantes, incluida una parrilla de mariscos junto al arrecife</li><li>Excursiones gratuitas para avistar tiburones ballena según la temporada</li></ul><p>Paquete de luna de miel: incluye champán, masaje en pareja, crucero privado al atardecer y cena romántica (estancia mínima de 5 noches)</p><p>Ideal para: parejas que buscan un servicio impecable y lujo</p><figure><img src="legacy/resorts/baros-island/images/baros-maldives-island-resort-beach-dinner.webp" alt="Baros Maldives beach dinner" loading="lazy" /></figure><h3>2. Baros Maldives</h3><p>Este íntimo resort boutique es perfecto para parejas que buscan privacidad:</p><ul><li>Solo 75 villas en una pequeña isla privada</li><li>Villas rodeadas de exuberante vegetación para máxima privacidad</li><li>Excelente arrecife propio accesible desde la playa</li><li>Icónico restaurante Lighthouse sobre la laguna</li><li>Experiencias románticas personalizadas</li></ul><p>Paquete de luna de miel: incluye champán, cesta de frutas, tratamiento de spa de 60 minutos y cena privada (estancia mínima de 4 noches)</p><p>Ideal para: parejas que valoran la intimidad y la belleza natural</p><h2>Los paquetes de luna de miel en Maldivas explicados</h2><figure><img src="legacy/images/romantic-sunrise-breakfast.webp" alt="Romantic breakfast in Maldives" loading="lazy" /></figure><p>Casi todos los resorts maldivos ofrecen paquetes especiales de luna de miel. Normalmente requieren un comprobante de matrimonio de los últimos 6 a 12 meses. Componentes clave:</p><h4>Inclusiones estándar:</h4><ul><li>Champán de bienvenida y cesta de frutas</li><li>Decoración romántica de la cama</li><li>Masaje en pareja (generalmente de 30 a 60 minutos)</li><li>Pastel o postre especial de luna de miel</li><li>Certificado conmemorativo o regalo</li></ul><h4>Extras premium:</h4><ul><li>Crucero privado al atardecer</li><li>Cena frente a la playa bajo las estrellas</li><li>Mejora garantizada de villa</li><li>Sesión de fotos con fotógrafo profesional</li><li>Excursiones personalizadas, como alquiler de yates privados</li></ul><h2>Experiencias románticas inolvidables</h2><figure><img src="legacy/images/articles/ozen-maadhoo-underwater-restaurant.webp" alt="Underwater restaurant Maldives" loading="lazy" /></figure><h4>1. Cenas bajo el agua</h4><p>Varios resorts cuentan con increíbles restaurantes submarinos donde se cena rodeado de vida marina. El más famoso es Ithaa, en el Conrad Maldives, el primer restaurante submarino del mundo construido totalmente de cristal.</p><figure><img src="legacy/images/stargazing-on-the-maldives-beach.webp" alt="Stargazing in Maldives" loading="lazy" /></figure><h4>2. Observación privada de estrellas</h4><p>Con una contaminación lumínica mínima, Maldivas ofrece cielos nocturnos espectaculares. Algunos resorts proporcionan telescopios y astrónomos que lo guiarán a través de las constelaciones mientras descansa en su terraza privada.</p>', 'Luna de miel en Maldivas: La guía definitiva para una escapada romántica | Guía de Viaje a Maldivas | MTG', 'Guía completa de luna de miel en Maldivas: descubra los mejores resorts románticos, bungalows sobre el agua, paquetes y experiencias únicas para su escapada en pareja perfecta en el paraíso.', 'published', 'claude')
on conflict (entity_id, locale) do update set
  slug = excluded.slug, title = excluded.title, short_description = excluded.short_description,
  body_html = excluded.body_html, meta_title = excluded.meta_title, meta_description = excluded.meta_description,
  translation_status = excluded.translation_status, translated_by = excluded.translated_by, updated_at = now();
